package main

// SageService holds everything the window calls. Exported methods become
// JavaScript functions (see frontend/bindings, generated by wails3).

import (
	"bufio"
	"bytes"
	"context"
	"crypto/rand"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"filippo.io/age"
	"filippo.io/age/armor"
	"github.com/wailsapp/wails/v3/pkg/application"
)

const (
	appTitle     = "sage v0.1.1"
	settingsFile = "sageSettings.json"
)

// Settings are saved next to the exe. Lines holding a secret key are never saved.
type Settings struct {
	ActiveTab      string `json:"activeTab"`
	Recipients     string `json:"recipients"`
	RecipientsFile string `json:"recipientsFile"`
	Identities     string `json:"identities"`
	Armor          bool   `json:"armor"`
	PostQuantum    bool   `json:"postQuantum"`
	// Notice is a one-time message from LoadSettings; it is never saved.
	Notice string `json:"notice,omitempty"`
}

// Request is the window's current state: what to process and how.
type Request struct {
	Files          []string `json:"files"`
	Mode           string   `json:"mode"` // "encrypt", "decrypt" or ""
	Tab            string   `json:"tab"`  // "passphrase" or "recipient"
	Passphrase     string   `json:"passphrase"`
	Confirm        string   `json:"confirm"`
	Recipients     string   `json:"recipients"`
	RecipientsFile string   `json:"recipientsFile"`
	Identities     string   `json:"identities"`
	Armor          bool     `json:"armor"`
	// PassInfo describes the passphrase fields without containing them. The
	// window sends this on every keystroke and the real passphrase only on Start.
	PassInfo *PassInfo `json:"passInfo"`
}

// PassInfo is what Status needs to know about the passphrase fields.
type PassInfo struct {
	Set        bool `json:"set"`
	ConfirmSet bool `json:"confirmSet"`
	Match      bool `json:"match"`
	LineBreak  bool `json:"lineBreak"`
}

func passInfoOf(r Request) PassInfo {
	if r.PassInfo != nil && r.Passphrase == "" && r.Confirm == "" {
		return *r.PassInfo
	}
	return PassInfo{
		Set:        r.Passphrase != "",
		ConfirmSet: r.Confirm != "",
		Match:      r.Passphrase == r.Confirm,
		LineBreak:  strings.ContainsAny(r.Passphrase+r.Confirm, "\r\n"),
	}
}

// Status drives the action button and the hint next to it.
type Status struct {
	Enabled bool   `json:"enabled"`
	Button  string `json:"button"`
	Hint    string `json:"hint"`
	Warn    bool   `json:"warn"`
}

// AddResult is the file list after adding paths.
type AddResult struct {
	Files []string `json:"files"`
	Mode  string   `json:"mode"`
	Note  string   `json:"note"`
	// Sizes in bytes, for the list's Size column.
	Sizes map[string]int64 `json:"sizes"`
}

// FileResult is what happened to one file in a job; the window shows it in that file's row.
type FileResult struct {
	Path      string `json:"path"`
	OK        bool   `json:"ok"`
	Output    string `json:"output"` // the file written, when OK
	Error     string `json:"error"`  // why it failed, in words a user can act on
	Cancelled bool   `json:"cancelled"`
}

// Progress is sent while a job runs.
type Progress struct {
	Done       int    `json:"done"`
	Total      int    `json:"total"`
	Bytes      int64  `json:"bytes"`
	BytesTotal int64  `json:"bytesTotal"`
	Current    string `json:"current"`
}

// JobDone is sent once when a job ends.
type JobDone struct {
	Summary   string       `json:"summary"`
	Remaining []string     `json:"remaining"`
	Results   []FileResult `json:"results"`
}

// KeyPair is the result of generating a new identity.
type KeyPair struct {
	Path      string `json:"path"`
	PublicKey string `json:"publicKey"`
}

func init() {
	application.RegisterEvent[FileResult]("job:file")
	application.RegisterEvent[Progress]("job:progress")
	application.RegisterEvent[JobDone]("job:done")
	application.RegisterEvent[[]string]("files:dropped")
}

type SageService struct {
	app         *application.App
	baseDir     string
	launchPaths []string

	mu             sync.Mutex
	running        bool
	cancel         context.CancelFunc
	inflight       sync.WaitGroup
	settingsBroken atomic.Bool

	onBytes func() // tests only: called as data is processed
}

func NewSageService(launchPaths []string) *SageService {
	dir := "."
	if exe, err := os.Executable(); err == nil {
		dir = filepath.Dir(exe)
	}
	return &SageService{baseDir: dir, launchPaths: launchPaths}
}

// ---------------------------------------------------------------- info and settings

func (s *SageService) Title() string { return appTitle }

// LaunchPaths returns the paths given on the command line (Explorer "Send to"),
// once.
func (s *SageService) LaunchPaths() []string {
	p := s.launchPaths
	s.launchPaths = nil
	return p
}

// LoadSettings reads sageSettings.json. A damaged file is kept as
// sageSettings.json.bad (so saving the defaults can't destroy it) and reported
// in Notice.
func (s *SageService) LoadSettings() Settings {
	st := Settings{ActiveTab: "passphrase"}
	path := filepath.Join(s.baseDir, settingsFile)
	data, err := os.ReadFile(path)
	if err == nil {
		// Notepad and PowerShell 5 may add a UTF-8 byte-order mark; that's not damage.
		data = bytes.TrimPrefix(data, []byte("\xef\xbb\xbf"))
		var loaded Settings
		if jsonErr := json.Unmarshal(data, &loaded); jsonErr != nil {
			bad := ""
			nameCandidates(path+".bad", func(candidate string) bool { // .bad, .bad (1), ...
				err := renameNoReplace(path, candidate)
				if err == nil {
					bad = candidate
					return false
				}
				return os.IsExist(err)
			})
			if bad != "" {
				st.Notice = fmt.Sprintf("The settings file was damaged and was not loaded (kept as %s).", filepath.Base(bad))
			} else {
				s.settingsBroken.Store(true) // can't move it aside: don't save over it
				st.Notice = "The settings file is damaged and could not be moved aside, so settings will not be saved until it is fixed or deleted."
			}
		} else {
			st = loaded
		}
	}
	if st.ActiveTab != "recipient" {
		st.ActiveTab = "passphrase"
	}
	return st
}

// withoutSecrets keeps what is safe to store in the settings file. It drops
// lines holding age secret keys, whole PEM blocks (e.g. a pasted SSH private
// key) and bare base64 blobs, which may be pieces of a key.
func withoutSecrets(text string) string {
	var keep []string
	inPEM := false
	for _, raw := range strings.Split(strings.TrimSpace(text), "\n") {
		line := strings.TrimRight(raw, "\r")
		trimmed := strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(trimmed, "-----BEGIN"):
			inPEM = true
			continue
		case strings.HasPrefix(trimmed, "-----END"):
			inPEM = false
			continue
		case inPEM, containsSecret(trimmed), looksLikeBase64Blob(trimmed):
			continue
		}
		keep = append(keep, line)
	}
	return strings.Join(keep, "\n")
}

// looksLikeBase64Blob matches a long run of base64 characters with nothing else
// on the line, as in the body of a PEM key. age recipients (age1..., lowercase
// bech32) and "ssh-ed25519 AAAA..." lines don't match.
func looksLikeBase64Blob(s string) bool {
	if len(s) < 40 || strings.HasPrefix(s, "age1") {
		return false
	}
	for _, c := range s {
		if !(c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '+' || c == '/' || c == '=') {
			return false
		}
	}
	return true
}

// SaveSettings writes to a temp file and renames it, so a crash can't wipe them.
func (s *SageService) SaveSettings(st Settings) error {
	if s.settingsBroken.Load() {
		return errors.New("the damaged settings file could not be moved aside, so settings are not saved")
	}
	st.Notice = ""
	st.Recipients = keepLines(st.Recipients, isRecipientLine)
	st.Identities = keepLines(st.Identities, looksLikePath)
	st.RecipientsFile = keepLines(st.RecipientsFile, looksLikePath)
	data, err := json.MarshalIndent(st, "", "  ")
	if err != nil {
		return err
	}
	path := filepath.Join(s.baseDir, settingsFile)
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
		return fmt.Errorf("settings can't be saved next to sage.exe: %v", err)
	}
	if err := os.Rename(tmp, path); err != nil { // replacing our own settings is intended
		os.Remove(tmp)
		return fmt.Errorf("settings can't be saved next to sage.exe: %v", err)
	}
	return nil
}

// ---------------------------------------------------------------- file list

// AddPaths adds dropped or chosen paths to the list.
func (s *SageService) AddPaths(existing, added []string) AddResult {
	expanded, skippedDirs, problems := expandPaths(added)
	if len(expanded) == 0 {
		note := "No files found in what was added."
		if len(problems) > 0 {
			note = "No files could be added:\n" + problemLines(problems)
		}
		return AddResult{Files: existing, Mode: modeOf(existing), Note: note, Sizes: sizesOf(existing)}
	}
	files, mode, ignored, duplicates := mergeFiles(existing, expanded)
	note := ""
	switch {
	case ignored > 0:
		note = fmt.Sprintf(".age files present: decrypt mode. Ignored %d other file(s).", ignored)
	case len(files) == len(existing) && duplicates > 0:
		note = "Those files are already in the list."
	}
	if skippedDirs > 0 {
		sub := fmt.Sprintf("%d subfolder(s) not included: a folder adds only the files directly inside it.", skippedDirs)
		if note != "" {
			note += "\n"
		}
		note += sub
	}
	if len(problems) > 0 {
		if note != "" {
			note += "\n"
		}
		note += "Not added:\n" + problemLines(problems)
	}
	return AddResult{Files: files, Mode: mode, Note: note, Sizes: sizesOf(files)}
}

// sizesOf returns each file's size for the list's Size column (missing files are left out).
func sizesOf(files []string) map[string]int64 {
	sizes := make(map[string]int64, len(files))
	for _, f := range files {
		if info, err := os.Stat(f); err == nil {
			sizes[f] = info.Size()
		}
	}
	return sizes
}

// problemLines lists unreadable paths, at most 5. (When sage runs as administrator
// the window shows the warning dialog and the Admin pill, so it isn't repeated here.)
func problemLines(problems []string) string {
	var b strings.Builder
	for i, p := range problems {
		if i < 5 {
			b.WriteString("  " + p + "\n")
		}
	}
	if len(problems) > 5 {
		fmt.Fprintf(&b, "  ...and %d more.\n", len(problems)-5)
	}
	return strings.TrimRight(b.String(), "\n")
}

const adminWarning = "Warning: sage is running as administrator. Windows hides drives mapped by your normal account from it, " +
	"also blocks drag & drop from Explorer. Close sage and start it normally."

// AdminWarning returns a warning when sage runs as administrator, for the window's
// warning dialog and Admin pill.
func (s *SageService) AdminWarning() string {
	if runningElevated() {
		return adminWarning
	}
	return ""
}

// GeneratePassphrase returns a random passphrase: 6 groups of 5 characters from a
// 31-character alphabet without look-alikes (i, l, o, 0, 1), about 148 bits.
func (s *SageService) GeneratePassphrase() (string, error) {
	const alphabet = "abcdefghjkmnpqrstuvwxyz23456789"
	limit := byte(256 - 256%len(alphabet)) // rejection sampling: no modulo bias
	var out []byte
	buf := make([]byte, 64)
	for len(out) < 30 {
		if _, err := rand.Read(buf); err != nil {
			return "", err
		}
		for _, b := range buf {
			if b < limit && len(out) < 30 {
				out = append(out, alphabet[int(b)%len(alphabet)])
			}
		}
	}
	groups := make([]string, 6)
	for i := range groups {
		groups[i] = string(out[i*5 : i*5+5])
	}
	return strings.Join(groups, "-"), nil
}

// OpenFolder shows a file in Explorer, selected (for a finished row's folder button).
func (s *SageService) OpenFolder(path string) error {
	if _, err := os.Stat(path); err != nil {
		return fmt.Errorf("%s isn't there any more", filepath.Base(path))
	}
	return showInExplorer(path)
}

func modeOf(files []string) string {
	_, mode, _, _ := mergeFiles(nil, files)
	return mode
}

// ---------------------------------------------------------------- status

// Status says whether the action can run and, if not, exactly what is missing.
func (s *SageService) Status(r Request) Status {
	if len(r.Files) == 0 {
		return Status{Button: "Encrypt", Hint: "Drop files or folders above, or click Files."}
	}
	// The mode comes from the files, never from the window.
	r.Mode = modeOf(r.Files)
	verb := "Encrypt"
	if r.Mode == "decrypt" {
		verb = "Decrypt"
	}
	button := fmt.Sprintf("%s %d file", verb, len(r.Files))
	if len(r.Files) != 1 {
		button += "s"
	}
	ready := "Ready. Output goes next to each file; existing files are never overwritten."

	if r.Tab != "recipient" {
		p := passInfoOf(r)
		switch {
		case !p.Set:
			return Status{Button: button, Hint: "Enter the passphrase."}
		case p.LineBreak:
			return Status{Button: button, Hint: "The passphrase contains a line break (pasted?). Remove it.", Warn: true}
		case r.Mode == "encrypt" && !p.ConfirmSet:
			return Status{Button: button, Hint: "Repeat the passphrase to confirm it."}
		case r.Mode == "encrypt" && !p.Match:
			return Status{Button: button, Hint: "Passphrases do not match.", Warn: true}
		}
		return Status{Enabled: true, Button: button, Hint: ready}
	}

	if r.Mode == "encrypt" {
		recs, desc, err := s.recipientsFor(r)
		if err != nil {
			return Status{Button: button, Hint: err.Error(), Warn: true}
		}
		if len(recs) == 0 {
			return Status{Button: button, Hint: "Add at least one recipient under 'Encrypt to', or a recipients file."}
		}
		return Status{Enabled: true, Button: button, Hint: "Ready: encrypting to " + desc + "."}
	}

	ids, err := identitiesFor(r)
	if err != nil {
		return Status{Button: button, Hint: err.Error(), Warn: true}
	}
	if len(ids) == 0 {
		return Status{Button: button, Hint: "Add an identity file under 'Decrypt with'."}
	}
	return Status{Enabled: true, Button: button, Hint: fmt.Sprintf("Ready: decrypting with %d key(s).", len(ids))}
}

// recipientsFor parses the "Encrypt to" box and the recipients file. Anything
// unusable is an error rather than silently skipped.
func (s *SageService) recipientsFor(r Request) ([]age.Recipient, string, error) {
	recs, err := parseRecipientText(r.Recipients)
	if err != nil {
		return nil, "", err
	}
	kinds := map[string]int{}
	for _, line := range meaningfulLines(r.Recipients) {
		kinds[recipientKind(line)]++
	}
	var parts []string
	if len(recs) > 0 {
		var names []string
		for k := range kinds {
			names = append(names, k)
		}
		parts = append(parts, fmt.Sprintf("%d recipient(s) (%s)", len(recs), strings.Join(sortedStrings(names), ", ")))
	}
	if path := strings.Trim(strings.TrimSpace(r.RecipientsFile), `"`); path != "" {
		fileRecs, err := parseRecipientsFile(path)
		if err != nil {
			return nil, "", err
		}
		recs = append(recs, fileRecs...)
		parts = append(parts, fmt.Sprintf("%d from the recipients file", len(fileRecs)))
	}
	if len(recs) > 0 {
		// age checks the combination only when encrypting, e.g. it refuses to mix
		// post-quantum and classic keys. Try it on nothing, so the hint can say so
		// before any file is touched.
		if _, err := age.Encrypt(io.Discard, recs...); err != nil {
			msg := err.Error()
			if strings.Contains(msg, "post-quantum and classic") {
				msg = "Post-quantum (age1pq1...) and classic keys can't be mixed in one file: the classic key would make it breakable by a quantum computer. Use one kind."
			}
			return nil, "", errors.New(msg)
		}
	}
	return recs, strings.Join(parts, " + "), nil
}

func identitiesFor(r Request) ([]age.Identity, error) {
	var ids []age.Identity
	for _, line := range meaningfulLines(r.Identities) {
		if containsSecret(line) {
			return nil, errors.New("a secret key was pasted into 'Decrypt with'; enter the key FILE's path instead")
		}
		got, err := parseIdentityFile(strings.Trim(line, `"`))
		if err != nil {
			return nil, err
		}
		ids = append(ids, got...)
	}
	return ids, nil
}

func sortedStrings(in []string) []string {
	out := append([]string{}, in...)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j] < out[j-1]; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// ---------------------------------------------------------------- the job

// Start runs a job in the background. Progress and results arrive as events.
func (s *SageService) Start(r Request) error {
	r.Mode = modeOf(r.Files) // decided here, never taken from the window
	r.PassInfo = nil         // judge the real passphrase, not the window's summary of it
	st := s.Status(r)
	if !st.Enabled {
		return errors.New(st.Hint)
	}
	encrypt := r.Mode == "encrypt"
	var recipients []age.Recipient
	var identities []age.Identity
	var err error
	if r.Tab == "recipient" {
		if encrypt {
			recipients, _, err = s.recipientsFor(r)
		} else {
			identities, err = identitiesFor(r)
		}
	} else if encrypt {
		var rec *age.ScryptRecipient
		rec, err = age.NewScryptRecipient(r.Passphrase)
		recipients = []age.Recipient{rec}
	} else {
		var id *age.ScryptIdentity
		id, err = age.NewScryptIdentity(r.Passphrase)
		identities = []age.Identity{id}
	}
	if err != nil {
		return err
	}

	s.mu.Lock()
	if s.running {
		s.mu.Unlock()
		return errors.New("a job is already running")
	}
	ctx, cancel := context.WithCancel(context.Background())
	s.running, s.cancel = true, cancel
	s.inflight.Add(1)
	s.mu.Unlock()

	files := append([]string{}, r.Files...)
	go func() {
		// Start owns the job's bookkeeping, so run can also be called directly (tests).
		defer func() {
			s.mu.Lock()
			s.running, s.cancel = false, nil
			s.mu.Unlock()
			s.inflight.Done()
		}()
		s.run(ctx, files, encrypt, recipients, identities, r.Armor && encrypt)
	}()
	return nil
}

func (s *SageService) run(ctx context.Context, files []string, encrypt bool,
	recipients []age.Recipient, identities []age.Identity, useArmor bool) JobDone {

	var total int64
	for _, f := range files {
		if info, err := os.Stat(f); err == nil {
			total += info.Size()
		}
	}
	var doneBytes atomic.Int64
	var pmu sync.Mutex // the ticker goroutine reads progress while the loop updates it
	progress := Progress{Total: len(files), BytesTotal: total}
	setProgress := func(done int, current string) {
		pmu.Lock()
		progress.Done, progress.Current = done, current
		pmu.Unlock()
	}
	emitProgress := func() {
		pmu.Lock()
		p := progress
		pmu.Unlock()
		p.Bytes = doneBytes.Load()
		if s.app != nil {
			s.app.Event.Emit("job:progress", p)
		}
	}
	stopTicker := make(chan struct{})
	go func() {
		t := time.NewTicker(150 * time.Millisecond)
		defer t.Stop()
		for {
			select {
			case <-t.C:
				emitProgress()
			case <-stopTicker:
				return
			}
		}
	}()

	// Each file's result goes to its row in the window as soon as it's known.
	var results []FileResult
	report := func(r FileResult) {
		results = append(results, r)
		if s.app != nil {
			s.app.Event.Emit("job:file", r)
		}
	}
	ok, failed := 0, 0
	var failedFiles, leftovers []string
	done := map[string]bool{}
	stopReason := ""
	for i, f := range files {
		if ctx.Err() != nil {
			break
		}
		setProgress(i, f)
		emitProgress()

		var counted int64
		out, err := processFile(ctx, f, encrypt, recipients, identities, useArmor, func(n int) {
			counted += int64(n)
			doneBytes.Add(int64(n))
			if s.onBytes != nil {
				s.onBytes() // tests only
			}
		})
		if err == nil {
			ok++
			done[f] = true
			report(FileResult{Path: f, OK: true, Output: out})
			continue
		}
		// The bytes of a failed file don't count as done.
		doneBytes.Add(-counted)
		var left *partLeftError
		if errors.As(err, &left) {
			leftovers = append(leftovers, left.Part)
		}
		if ctx.Err() != nil {
			msg := "Cancelled; nothing was written."
			if left != nil {
				msg = "Cancelled; the partial file couldn't be deleted (see below)."
			}
			report(FileResult{Path: f, Cancelled: true, Error: msg})
			break
		}
		failed++
		failedFiles = append(failedFiles, f)
		report(FileResult{Path: f, Error: friendlyError(err)})
		// A wrong key on the first file stops the batch: every further file would
		// cost another slow key derivation and fail the same way.
		if isWrongKey(err) && ok == 0 {
			stopReason = "after a wrong passphrase or key"
			break
		}
	}
	close(stopTicker)
	setProgress(ok+failed, "")
	emitProgress()

	summary := fmt.Sprintf("Finished: %d OK, %d failed", ok, failed)
	if skipped := len(files) - ok - failed; skipped > 0 {
		why := "cancelled"
		if stopReason != "" {
			why = stopReason
		}
		summary += fmt.Sprintf(", %d not processed (%s)", skipped, why)
	}
	summary += "."
	if len(leftovers) > 0 {
		summary += "\nPartial output that couldn't be deleted (in use?); delete it yourself:"
		for _, p := range leftovers {
			summary += "\n  " + withoutLongPrefix(p)
		}
	}

	// Failed and unprocessed files stay in the list for a retry, failed ones last.
	isFailed := map[string]bool{}
	for _, f := range failedFiles {
		isFailed[f] = true
	}
	var remaining []string
	for _, f := range files {
		if !done[f] && !isFailed[f] {
			remaining = append(remaining, f)
		}
	}
	remaining = append(remaining, failedFiles...)
	result := JobDone{Summary: summary, Remaining: remaining, Results: results}
	if s.app != nil {
		s.app.Event.Emit("job:done", result)
	}
	return result
}

// Cancel stops the running job; the current file's partial output is deleted.
func (s *SageService) Cancel() {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.cancel != nil {
		s.cancel()
	}
}

// Shutdown cancels a running job and waits briefly for it to clean up.
func (s *SageService) ServiceShutdown() error {
	s.Cancel()
	finished := make(chan struct{})
	go func() { s.inflight.Wait(); close(finished) }()
	select {
	case <-finished:
	case <-time.After(5 * time.Second):
	}
	return nil
}

// ---------------------------------------------------------------- dialogs

func (s *SageService) ChooseFiles() []string {
	paths, err := s.app.Dialog.OpenFile().CanChooseFiles(true).SetTitle("Add files").PromptForMultipleSelection()
	if err != nil {
		return nil
	}
	return paths
}

func (s *SageService) ChooseFolder() string {
	path, err := s.app.Dialog.OpenFile().CanChooseFiles(false).CanChooseDirectories(true).
		SetTitle("Add folder").PromptForSingleSelection()
	if err != nil {
		return ""
	}
	return path
}

func (s *SageService) ChooseRecipientsFile() string {
	path, err := s.app.Dialog.OpenFile().CanChooseFiles(true).SetTitle("Recipients file").PromptForSingleSelection()
	if err != nil {
		return ""
	}
	return path
}

func (s *SageService) ChooseIdentityFiles() []string {
	paths, err := s.app.Dialog.OpenFile().CanChooseFiles(true).SetTitle("Identity (secret key) files").
		PromptForMultipleSelection()
	if err != nil {
		return nil
	}
	return paths
}

// ---------------------------------------------------------------- keys and inspect

// GenerateKey asks for a folder and writes a new identity file there, named
// age-key.txt or age-key (N).txt. A folder picker is used instead of a save
// dialog because Windows' save dialog offers to "replace" an existing file,
// which sage would then refuse to do.
func (s *SageService) GenerateKey(postQuantum bool) (KeyPair, error) {
	dir, err := s.app.Dialog.OpenFile().CanChooseFiles(false).CanChooseDirectories(true).
		SetTitle("Folder for the new identity (secret key) file").PromptForSingleSelection()
	if err != nil || dir == "" {
		return KeyPair{}, errors.New("cancelled")
	}
	return newIdentityIn(dir, postQuantum)
}

// newIdentityIn writes a new identity file into dir under the first free name.
func newIdentityIn(dir string, postQuantum bool) (KeyPair, error) {
	var kp KeyPair
	var lastErr error
	nameCandidates(filepath.Join(dir, "age-key.txt"), func(candidate string) bool {
		kp, lastErr = writeNewIdentity(candidate, postQuantum)
		return lastErr != nil && errors.Is(lastErr, os.ErrExist) // name taken: try the next
	})
	return kp, lastErr
}

// writeNewIdentity creates path exclusively; it fails with os.ErrExist rather
// than replace an existing file.
func writeNewIdentity(path string, postQuantum bool) (KeyPair, error) {
	var secret, public string
	if postQuantum {
		id, err := age.GenerateHybridIdentity()
		if err != nil {
			return KeyPair{}, err
		}
		secret, public = id.String(), id.Recipient().String()
	} else {
		id, err := age.GenerateX25519Identity()
		if err != nil {
			return KeyPair{}, err
		}
		secret, public = id.String(), id.Recipient().String()
	}
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		if os.IsExist(err) {
			return KeyPair{}, fmt.Errorf("%s already exists; a key file is never overwritten: %w", filepath.Base(path), os.ErrExist)
		}
		return KeyPair{}, err
	}
	// Same layout as age-keygen.
	_, err = fmt.Fprintf(f, "# created: %s\n# public key: %s\n%s\n", time.Now().Format(time.RFC3339), public, secret)
	if closeErr := f.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		os.Remove(path)
		return KeyPair{}, err
	}
	return KeyPair{Path: path, PublicKey: public}, nil
}

// Inspect describes the .age files in the list without decrypting them.
func (s *SageService) Inspect(files []string) string {
	var out []string
	for _, f := range files {
		if isAgeFile(f) {
			out = append(out, inspectFile(f))
		}
	}
	return strings.Join(out, "\n\n")
}

// inspectFile reports what age-inspect reports: the recipient types and whether
// the file is post-quantum. The classification is age's own (internal/inspect).
func inspectFile(path string) string {
	name := filepath.Base(path)
	f, err := os.Open(path)
	if err != nil {
		return name + ": " + err.Error()
	}
	defer f.Close()
	b := bufio.NewReader(f)
	var r io.Reader = b
	armored := false
	if p, _ := b.Peek(len(armor.Header) + 1024); bytes.HasPrefix(bytes.TrimSpace(p), []byte(armor.Header)) {
		r, armored = armor.NewReader(b), true
	}
	header, err := age.ExtractHeader(r)
	if err != nil {
		return name + ": not a valid age file (" + err.Error() + ")"
	}
	var types []string
	pq := "yes"
	for _, line := range strings.Split(string(header), "\n") {
		if !strings.HasPrefix(line, "-> ") {
			continue
		}
		t := strings.Fields(line[3:])
		if len(t) == 0 {
			continue
		}
		types = append(types, t[0])
		switch t[0] {
		case "X25519", "ssh-rsa", "ssh-ed25519", "p256tag", "piv-p256":
			pq = "no"
		case "mlkem768x25519", "scrypt", "mlkem768p256tag":
		default:
			if pq != "no" {
				pq = "unknown"
			}
		}
	}
	lines := []string{name + " is an age file."}
	if armored {
		lines = append(lines, "  ASCII-armored.")
	}
	lines = append(lines, "  Encrypted to: "+strings.Join(types, ", "))
	switch pq {
	case "yes":
		lines = append(lines, "  Uses post-quantum encryption.")
	case "no":
		lines = append(lines, "  Does NOT use post-quantum encryption.")
	default:
		lines = append(lines, "  Unknown whether it uses post-quantum encryption.")
	}
	if len(types) == 1 && types[0] == "scrypt" {
		lines = append(lines, "  (scrypt = passphrase.)")
	}
	return strings.Join(lines, "\n")
}
